#!/bin/bash
set -euo pipefail

# Mistral Vibe Agent - PR Creation
# Creates draft PRs for Vibe implementations

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "${SCRIPT_DIR}/common.sh"

create_working_branch() {
    local branch_name="$1"
    log_info "Creating working branch: ${branch_name}"
    
    if is_dry_run; then
        log_info "[DRY RUN] Would create branch: ${branch_name}"
        return 0
    fi
    
    # Fetch latest main
    git fetch origin main
    git checkout -B main FETCH_HEAD
    
    # Create new branch
    if git checkout -b "$branch_name"; then
        log_info "Branch created: ${branch_name}"
        return 0
    else
        log_error "Failed to create branch: ${branch_name}"
        return 1
    fi
}

# Create a draft PR
create_draft_pr() {
    local branch_name="$1"
    local issue_number="$2"
    local issue_data issue_title issue_body
    
    issue_data=$(get_issue_details "$issue_number")
    issue_title=$(echo "$issue_data" | jq -r '.title')
    issue_body=$(echo "$issue_data" | jq -r '.body')
    
    log_info "Creating draft PR for branch: ${branch_name}"
    
    if is_dry_run; then
        log_info "[DRY RUN] Would create draft PR for branch: ${branch_name}"
        echo "https://github.com/${GITHUB_REPO}/pull/new/${branch_name}"
        return 0
    fi
    
    # Get commit messages
    local commits
    commits=$(git log --pretty=format:"%s" "main..${branch_name}" 2>/dev/null || echo "")
    
    # Build PR description
    local pr_body
    pr_body=$(build_pr_description "$issue_number" "$issue_title" "$issue_body" "$commits")
    
    local pr_title
    pr_title="vibe: ${issue_title}"
    
    local pr_url
    pr_url=$(gh pr create --repo "$GITHUB_REPO" --head "$branch_name" \
        --base main --draft --title "$pr_title" --body-file - <<< "$pr_body") || return 1
    [[ -n "$pr_url" ]] || { log_error "Failed to create PR"; return 1; }

    log_info "Draft PR created: ${pr_url}"
    
    # Add comment to original issue
    local comment_body
    printf -v comment_body "I've created a draft PR to implement this issue: %s\n\nPlease review and let me know if any changes are needed." "$pr_url"
    
    gh issue comment "$issue_number" --repo "$GITHUB_REPO" --body-file - \
        <<< "$comment_body" > /dev/null || log_warn "Could not comment on issue #${issue_number}"
    
    echo "$pr_url"
    return 0
}

# Build PR description
build_pr_description() {
    local issue_number="$1"
    local issue_title="$2"
    local issue_body="$3"
    local commits="$4"
    
    cat <<EOF
## Implements #${issue_number}: ${issue_title}

${issue_body}

---

### Changes

$(printf '%s\n' "$commits" | sed 's/^/- /')

### Testing
- [ ] Review the build results and test coverage
- [ ] Manual testing required

### Review Checklist
- [ ] Code follows existing patterns
- [ ] Tests are comprehensive
- [ ] Documentation is updated
- [ ] No breaking changes

---

*Generated by Mistral Vibe Agent*
*Co-Authored-By: Mistral Vibe <vibe@mistral.ai>*
EOF
}

# Commit changes
commit_changes() {
    local issue_number="$1"
    local message="$2"
    
    log_info "Committing changes: ${message}"
    
    if is_dry_run; then
        log_info "[DRY RUN] Would commit: ${message}"
        return 0
    fi
    
    git add -A
    
    if git diff --cached --quiet; then
        log_info "No changes to commit"
        return 1
    fi

    local commit_message
    printf -v commit_message '%s\n\nImplements #%s\n\nGenerated by Mistral Vibe.\nCo-Authored-By: Mistral Vibe <vibe@mistral.ai>' "$message" "$issue_number"
    
    if git commit -m "$commit_message"; then
        log_info "Changes committed"
        return 0
    else
        log_error "Failed to commit changes"
        return 1
    fi
}
